// GET /api/fees — total creator fees generated by $YIPPEE for charity, and how much is waiting to be claimed.
//
// How pump.fun routes $YIPPEE fees (read from chain):
//   trades -> creator vault (PDA of the fee-sharing config) -> donation account -> 4 charities (25% each)
// Charities claim whenever they like (pump.fun automates it), so:
//   waiting = what is sitting in the creator vault(s) right now
//   claimed = everything that has left the vault(s) in transactions that touch the donation account
//   total   = claimed + waiting
//
// Set HELIUS_API_KEY in Vercel project settings. Without it the public Solana RPC is used (slow + rate limited).

const DONATION = '5BnNQt7fhaofQYtrGYpMi1bzZABoz8npwE466Mx6kRAD'; // pump.fun donation account (100% of fees)
const VAULT = '5LDC2oS4uxAgMht65pkSKb9cQ4uRzL5ztzjrQFo6KehD'; // bonding-curve creator vault (SOL)
const AMM_VAULT = '5GT7aW7j6W3xiakjEp1sSASehj9HC833vgH85fnKU2Fw'; // PumpSwap creator vault (WSOL) — used after graduation
const RENT_MIN = 890880; // lamports a 0-byte system account must keep

const rpcUrl = () =>
  process.env.HELIUS_API_KEY
    ? `https://mainnet.helius-rpc.com/?api-key=${process.env.HELIUS_API_KEY}`
    : 'https://api.mainnet-beta.solana.com';

async function rpc(method, params, tries = 4) {
  for (let i = 0; i < tries; i++) {
    const r = await fetch(rpcUrl(), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
    });
    if (r.status === 429) { await new Promise((s) => setTimeout(s, 600 * (i + 1))); continue; }
    const j = await r.json();
    if (j.error) throw new Error(`${method}: ${j.error.message}`);
    return j.result;
  }
  throw new Error(`${method}: rate limited`);
}

async function waitingLamports() {
  const [sol, wsol] = await Promise.all([
    rpc('getBalance', [VAULT]).then((r) => Math.max(0, r.value - RENT_MIN)),
    rpc('getTokenAccountBalance', [AMM_VAULT]).then((r) => Number(r.value.amount)).catch(() => 0),
  ]);
  return sol + wsol;
}

async function allSignatures(address) {
  const out = [];
  let before;
  for (let page = 0; page < 20; page++) {
    const batch = await rpc('getSignaturesForAddress', [address, { limit: 1000, before }]);
    out.push(...batch.filter((s) => !s.err));
    if (batch.length < 1000) break;
    before = batch[batch.length - 1].signature;
  }
  return out;
}

// Lamports that left the creator vault(s) in one transaction.
function vaultOutflow(tx) {
  const keys = tx.transaction.message.accountKeys.map((k) => (typeof k === 'string' ? k : k.pubkey));
  let out = 0;
  const i = keys.indexOf(VAULT);
  if (i >= 0) out += Math.max(0, tx.meta.preBalances[i] - tx.meta.postBalances[i]);
  const j = keys.indexOf(AMM_VAULT);
  if (j >= 0) {
    const amt = (list) => Number((list || []).find((b) => b.accountIndex === j)?.uiTokenAmount.amount || 0);
    out += Math.max(0, amt(tx.meta.preTokenBalances) - amt(tx.meta.postTokenBalances));
  }
  return out;
}

async function claimedLamports() {
  const sigs = await allSignatures(DONATION);
  let total = 0;
  for (let k = 0; k < sigs.length; k += 8) {
    const txs = await Promise.all(
      sigs.slice(k, k + 8).map((s) =>
        rpc('getTransaction', [s.signature, { maxSupportedTransactionVersion: 1, encoding: 'jsonParsed' }])
      )
    );
    for (const tx of txs) if (tx && !tx.meta.err) total += vaultOutflow(tx);
  }
  return total;
}

async function solUsd() {
  try {
    const r = await fetch('https://api.coingecko.com/api/v3/simple/price?ids=solana&vs_currencies=usd');
    const j = await r.json();
    return j.solana.usd || null;
  } catch (_) {
    return null;
  }
}

module.exports = async function handler(req, res) {
  try {
    const [waiting, claimed, price] = await Promise.all([waitingLamports(), claimedLamports(), solUsd()]);
    const totalSol = (waiting + claimed) / 1e9;
    const waitingSol = waiting / 1e9;
    res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
    res.status(200).json({
      totalSol,
      waitingSol,
      claimedSol: claimed / 1e9,
      solUsd: price,
      totalUsd: price ? totalSol * price : null,
      waitingUsd: price ? waitingSol * price : null,
      donationAccount: DONATION,
      vault: VAULT,
      updatedAt: new Date().toISOString(),
    });
  } catch (e) {
    res.setHeader('Cache-Control', 'no-store');
    res.status(502).json({ error: 'Could not read on-chain data right now.' });
  }
};
